import { Component, Input } from '@angular/core';
import { Bs2DSCardProductComponent } from './bs2-ds-card-product.component';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { delay, finalize } from 'rxjs/operators';
import { of } from 'rxjs';

function rand(min: number, max: number) {
  return Math.floor(Math.random() * (max - min + 1) + min);
}

@Component({
  selector: 'father-simulation',
  styles: `:host{ display:block; width: 231px; }`,
  template: `<bs2-ds-card-product
    [testId]="testId"
    [loader]="loader"
    [unavailableTitle]="unavailableTitle"
    [icon]="icon"
    [title]="title"
    [label]="label"
    [value]="value"
    [text]="text"
    [template]="template"
    (update)="update()"
  />`,
  standalone: true,
  imports: [Bs2DSCardProductComponent],
})
class FatherSimulationComponent {
  @Input() testId? = '';
  @Input() loader? = false;
  @Input() unavailableTitle? = '';
  @Input() icon? = '';
  @Input() title? = '';
  @Input() label? = '';
  @Input() value?: number;
  @Input() text? = '';
  @Input() template: 'visible' | 'hidden' | 'unavailable' = 'visible';

  update() {
    this.loader = true;
    of(null)
      .pipe(
        delay(3000),
        finalize(() => (this.loader = false))
      )
      .subscribe(() => {
        this.template = 'visible';
        this.value = rand(1, 1000000000);
      });
  }
}

const meta: Meta<FatherSimulationComponent> = {
  component: FatherSimulationComponent,
  title: 'Components/Card Product',
  subcomponents: {
    Bs2DSCardProductComponent,
  },
  decorators: [
    moduleMetadata({
      imports: [FatherSimulationComponent, Bs2DSCardProductComponent],
    }),
  ],
  argTypes: {
    loader: {
      control: 'boolean',
      defaultValue: { summary: 'false' },
      table: {
        type: {
          summary: 'false',
        },
      },
    },
    unavailableTitle: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    icon: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    title: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    label: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    value: {
      control: { type: 'number' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'number',
        },
      },
    },
    text: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    template: {
      control: 'select',
      options: ['visible', 'hidden', 'unavailable'],
      defaultValue: { summary: 'visible' },
      table: {
        type: {
          summary: 'visible | hidden | unavailable',
        },
      },
    },
    update: {
      defaultValue: { summary: 'EventEmitter' },
      table: {
        type: {
          detail:
            "APENAS para documentação, esse EventEmitter esta setando [template='visible'] após um Observable de 3000ms.",
          summary: 'new EventEmitter',
        },
      },
    },
    testId: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
  },
};
export default meta;
type Story = StoryObj<FatherSimulationComponent>;

export const Visible: Story = {
  args: {
    title: 'Crédito',
    label: 'Limite disponível até',
    value: 50000,
  },
};

export const Hidden: Story = {
  args: {
    title: 'Crédito',
    label: 'Limite disponível até',
    value: 50000,
    template: 'hidden',
  },
};

export const TextOnly: Story = {
  args: {
    title: 'Label',
    text: 'Lorem ipsum pimentbus ardentis queimatuns est labiatuns',
    testId: '',
  },
};

export const Unavailable: Story = {
  args: {
    unavailableTitle: 'Unavailable title',
    title: 'Crédito',
    label: 'Limite disponível até',
    template: 'unavailable',
    testId: '',
  },
};

import { Component, Input } from '@angular/core';
import { Bs2DSCardBalanceComponent } from './bs2-ds-card-balance.component';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { delay, finalize } from 'rxjs/operators';
import { of } from 'rxjs';

function rand(min: number, max: number) {
  return Math.floor(Math.random() * (max - min + 1) + min);
}

@Component({
  selector: 'father-simulation',
  styles: `:host{ display:block; width: 312px; }`,
  template: `<bs2-ds-card-balance
    [loader]="loader"
    [testId]="testId"
    [balance]="balance"
    [limit]="limit"
    [template]="template"
    (update)="update()"
  />`,
  standalone: true,
  imports: [Bs2DSCardBalanceComponent],
})
class FatherSimulationComponent {
  @Input() loader? = false;
  @Input() testId? = '';
  @Input() balance? = 0;
  @Input() limit? = 0;
  @Input() template: 'visible' | 'hidden' | 'unavailable' = 'visible';

  update() {
    this.loader = true;
    of(null)
      .pipe(
        delay(3000),
        finalize(() => (this.loader = false))
      )
      .subscribe(() => {
        this.template = 'visible';
        this.balance = rand(1, 1000000000);
        this.limit = rand(1, 300000000);
      });
  }
}

const meta: Meta<FatherSimulationComponent> = {
  component: FatherSimulationComponent,
  title: 'Components/Card Balance',
  subcomponents: {
    Bs2DSCardBalanceComponent,
  },
  decorators: [
    moduleMetadata({
      imports: [FatherSimulationComponent, Bs2DSCardBalanceComponent],
    }),
  ],
  argTypes: {
    balance: {
      control: { type: 'number' },
      defaultValue: { summary: '0' },
      table: {
        type: {
          summary: 'number',
        },
      },
    },
    limit: {
      control: { type: 'number' },
      defaultValue: { summary: '0' },
      table: {
        type: {
          summary: 'number',
        },
      },
    },
    template: {
      control: 'select',
      options: ['visible', 'hidden', 'unavailable'],
      defaultValue: { summary: 'visible' },
      table: {
        type: {
          summary: 'visible | hidden | unavailable',
        },
      },
    },
    loader: {
      control: 'boolean',
      defaultValue: { summary: 'false' },
      table: {
        type: {
          summary: 'false',
        },
      },
    },
    update: {
      defaultValue: { summary: 'EventEmitter' },
      table: {
        type: {
          detail:
            "APENAS para documentação, esse EventEmitter esta setando [template='visible'] após um Observable de 3000ms.",
          summary: 'new EventEmitter',
        },
      },
    },
    testId: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
  },
};
export default meta;
type Story = StoryObj<FatherSimulationComponent>;

export const Visible: Story = {
  args: {
    balance: 1000000000.12,
    limit: 3000000000.23,
    template: 'visible',
  },
};

export const Hidden: Story = {
  args: {
    balance: 1000000000.12,
    limit: 3000000000.23,
    template: 'hidden',
  },
};

export const Unavailable: Story = {
  args: {
    template: 'unavailable',
  },
};

import { Bs2DSFeedbackService } from './bs2-ds-feedback.service';
import { Bs2DSFeedbackComponent } from './bs2-ds-feedback.component';
import { Bs2DSFilledButtonDirective } from '@bs2/design-system/directives/bs2-ds-button/bs2-ds-filled-button';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import { Component, inject, Input } from '@angular/core';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations';
import { Bs2DSFeedbackContainerComponent } from '../bs2-ds-feedback-container/bs2-ds-feedback-container.component';

@Component({
  selector: 'button-mock',
  template: `
    <bs2-ds-feedback-container />
    <p>Para fazer o uso do toast, é necessário usar a service Bs2DSFeedbackService.</p>
    <button
      bs2-ds-filled-button
      (click)="
        feedbackService.add({ title: this.title, message: this.message, status: this.status, duration: this.duration })
      "
      aria-label="label"
    >
      Abrir Toast
    </button>
  `,
  standalone: true,
  imports: [Bs2DSFeedbackContainerComponent, Bs2DSFilledButtonDirective],
})
class MockBs2DSFeedbackComponent {
  @Input() testId? = '';
  @Input() status: 'info' | 'attention' | 'error' | 'success' = 'info';
  @Input() duration?: number;
  @Input() title = '';
  @Input() message = '';

  public feedbackService = inject(Bs2DSFeedbackService);
}

const meta: Meta<MockBs2DSFeedbackComponent> = {
  component: MockBs2DSFeedbackComponent,
  title: 'Components/Feedback',
  subcomponents: {
    Bs2DSFeedbackComponent,
  },
  decorators: [
    moduleMetadata({
      imports: [
        MockBs2DSFeedbackComponent,
        Bs2DSFeedbackComponent,
        Bs2DSFeedbackComponent,
        Bs2DSFilledButtonDirective,
        Bs2DSFeedbackContainerComponent,
        BrowserAnimationsModule,
      ],
    }),
  ],
  argTypes: {
    title: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    message: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
    status: {
      control: 'select',
      options: ['info', 'attention', 'error', 'success'],
      defaultValue: { summary: 'visible' },
      table: {
        type: {
          summary: 'info | attention | error | success',
        },
      },
    },
    duration: {
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'number | undefined',
        },
      },
    },
    testId: {
      control: { type: 'text' },
      defaultValue: { summary: '(vazio)' },
      table: {
        type: {
          summary: 'string',
        },
      },
    },
  },
};
export default meta;
type Story = StoryObj<MockBs2DSFeedbackComponent>;

export const Static: Story = {
  args: {
    title: 'Lorem ipsum dolor title',
    message: 'Lorem ipsum dolor message',
  },
  render: (args: MockBs2DSFeedbackComponent) => {
    return {
      template: `
        <bs2-ds-feedback status='info' title='${args.title}' message='${args.message}' /><br/>
        <bs2-ds-feedback status='attention' title='${args.title}' message='${args.message}' /><br/>
        <bs2-ds-feedback status='error' title='${args.title}' message='${args.message}' /><br/>
        <bs2-ds-feedback status='success' title='${args.title}' message='${args.message}' />
      `,
    };
  },
};

export const Toast: Story = {
  args: {
    title: 'Lorem ipsum dolor title',
    message: 'Lorem ipsum dolor message',
    status: 'success',
  },
};

