};

export const Offset: Story = {
  render: () => ({
    template: `
      ${boxStyle}
        <div bs2-ds-row gap='30px'>
          ${column(1, [4], [0, 6, 3])}
          ${column(1, [4], [1])}
        </div>
    `,
  }),
};

export const Push: Story = {
  render: () => ({
