{
  render: () => {
    const control = new FormControl([]);
    const options = [
      { id: 1, text: 'Banana' },
      { id: 2, text: 'Maça' },
      { id: 3, text: 'Uva' },
    ];

    const emitter = () => {
      if (control.value.length === options.length) return control.setValue([]);
      if (control.value.length >= 0) return control.setValue(options.map((item) => item.id));
    };

    return {
      props: {
        control,
        options,
        emitter,
      },
      template: `
        <bs2-ds-selectors
          type="checkbox"
          [control]="control"
          value="Todos"
          [isMain]="true"
          [totalItemsCount]="options.length"
          (emitter)="emitter($event)"
        >
          <ng-template>Todos</ng-template>
        </bs2-ds-selectors>

        <ng-container *ngFor="let item of options">
          <bs2-ds-selectors
            type="checkbox"
            [control]="control"
            [value]="item.id"
          >
            <ng-template>{{ item.text }}</ng-template>
          </bs2-ds-selectors>
        </ng-container>
      `,
    };
  },
}

(amount: number, columns?: number[], offsets?: number[], pushs?: number[], orders?: number[]) =>
  Array(amount)
    .fill(0)
    .map(
      () =>
        `<div
            ${(columns || []).length > 0 ? `[bs2-ds-column]="${JSON.stringify(columns || [])}"` : ''}
            ${(offsets || []).length > 0 ? `[bs2-ds-offset]="${JSON.stringify(offsets || [])}"` : ''}
            ${(pushs || []).length > 0 ? `[bs2-ds-push]="${JSON.stringify(pushs || [])}"` : ''}
            ${(orders || []).length > 0 ? `[bs2-ds-order]="${JSON.stringify(orders || [])}"` : ''}
          >
            <span class='box'>
              ${(columns || []).length > 0 ? `columns: ${getBreakpoints(columns)}` : ''}
              ${(offsets || []).length > 0 ? `offsets: ${getBreakpoints(offsets)}` : ''}
              ${(pushs || []).length > 0 ? `pushs: ${getBreakpoints(pushs)}` : ''}
              ${(orders || []).length > 0 ? `orders: ${getBreakpoints(orders)}` : ''}
            </span>
          </div>`
    )
    .join('')

